std::vector<T> binCounts(numBins);
for (int i = 0; i < numBins; i++) {
    binCentersX[i] = bins->binCenters[i].x;
    binCentersY[i] = bins->binCenters[i].y;
    binCentersZ[i] = bins->binCenters[i].z;
    binCounts[i] = bins->binCounts[i];
}

T minCost = std::numeric_limits<T>::max();
int minCostAxis = -1;
for (int axis = 0; axis < 3; axis++) {
    std::vector<T> binCenters, binCountsCopy = binCounts;
    if (axis == 0) {
        binCenters = binCentersX;
    } else if (axis == 1) {
        binCenters = binCentersY;
    } else {
        binCenters = binCentersZ;
    }

    std::sort(binCenters.begin(), binCenters.end());
    T leftSum = 0, rightSum = 0;
    for (int i = 0; i < numBins; i++) {
        rightSum += binCountsCopy[i];
    }

    T bestCost = std::numeric_limits<T>::max();
    T bestCutPos = 0;
    for (int i = 0; i < numBins - 1; i++) {
        leftSum += binCountsCopy[i];
        rightSum -= binCountsCopy[i];
        T cost = leftSum * (binCenters[i + 1] - bmin[axis]) + rightSum * (bmax[axis] - binCenters[i]);
        if (cost < bestCost) {
            bestCost = cost;
            bestCutPos = (binCenters[i] + binCenters[i + 1]) / 2;
        }
    }

    if (bestCost < minCost) {
        minCost = bestCost;
        minCostAxis = axis;
        cut_pos[axis] = bestCutPos;
    }
}

*minCostAxis = minCostAxis;
return minCostAxis != -1;

